/// Stockman & Sharpe (2000) 10° cone fundamentals at 1nm spacing
///
/// Linear interpolation from 5nm data, normalized so each channel sums to 1.0. Data spans 390nm to 830nm with 1nm spacing (441 wavelength samples). 3-channel interleaved format: [L, M, S] at each wavelength.
pub const LMS_2000_10DEG_1NM: ConstSpectrum = ConstSpectrum {
    start_nm: 390.0,
    stop_nm: 830.0,
    spacing_nm: 1.0,
    num_channels: 3,
    data: &LMS_2000_10DEG_1NM_DATA,
};

/// VSF RGB → lms transformation matrix
///
/// Converts linear VSF RGB (703nm, 523nm, 462nm primaries) to normalized lms cone space. Derived from Stockman & Sharpe (2000) 10° cone fundamentals with white point scaling so that RGB=[1,1,1] maps to Illuminant E (equal energy spectrum).
///
/// Matrix layout (column-major):
/// - Indices 0-2: Red primary's [L, M, S] cone responses
/// - Indices 3-5: Green primary's [L, M, S] cone responses
/// - Indices 6-8: Blue primary's [L, M, S] cone responses
pub const VSF_RGB2LMS: [f32; 9] = [
    0.358_562_77_f32,
    0.024_773_11_f32,
    0.000_000_427_165_5_f32,
    0.559_762_66_f32,
    0.809_180_2_f32,
    0.018_622_711_f32,
    0.081_674_57_f32,
    0.166_046_68_f32,
    0.981_376_9_f32,
];

/// lms → VSF RGB transformation matrix
///
/// Converts normalized lms cone space to linear VSF RGB. Inverse of VSF_RGB2LMS.
pub const LMS2VSF_RGB: [f32; 9] = [
    2.929_061_7_f32,
    -0.090_023_72_f32,
    0.001_707_024_6_f32,
    -2.028_511_5_f32,
    1.302_995_3_f32,
    -0.024_724_893_f32,
    0.099_449_806_f32,
    -0.212_971_58_f32,
    1.023_017_9_f32,
];

/// lms → Photopic luminance weights
///
/// CIE 170-2 / Stockman & Sharpe 10° luminous efficiency V*₁₀(λ) = 0.692839·l̄(λ) + 0.349676·m̄(λ) (defined on unit-peak energy fundamentals), converted to VSF's sum-normalized basis via w = coefficient/max(channel).
/// Reconstructs unit-peak V*₁₀ from the sum-normalized channels; downstream white normalization (PHOTOPIC_WHITE_NORM) handles absolute scale.
pub const LMS2PHOTOPIC: [f32; 3] = [
    84.18661_f32,  // l cone weight
    36.098335_f32, // m cone weight
    0.0,           // s cone weight (S-cones don't contribute to photopic luminance)
];

